import Foundation
import simd

// Shared fixtures with the Viro tests (generated by scripts/generate-fixtures.py).
func fixture(_ name: String) -> [String: Any] {
    let url = URL(fileURLWithPath: "Tests/fixtures/\(name)")
    return try! JSONSerialization.jsonObject(with: Data(contentsOf: url)) as! [String: Any]
}
func doubles(_ value: Any?) -> [Double] { (value as! [Any]).map { ($0 as! NSNumber).doubleValue } }
func vec(_ value: Any?) -> Vec3 { MatrixMath.vec(doubles(value))! }
func mat(_ value: Any?) -> Mat4 { MatrixMath.matrix(doubles(value))! }
func check(_ condition: Bool, _ message: @autoclosure () -> String) {
    if !condition { print("FAIL: \(message())"); exit(1) }
}
func near(_ a: Double, _ b: Double, _ tolerance: Double = 1e-9, _ label: String = "") {
    check(abs(a - b) <= tolerance, "\(label) \(a) != \(b) ±\(tolerance)")
}
func nearAll(_ a: [Double], _ b: [Double], _ tolerance: Double = 1e-9, _ label: String = "") {
    for (i, (x, y)) in zip(a, b).enumerated() { near(x, y, tolerance, "\(label)[\(i)]") }
}
func angleDeg(_ a: Vec3, _ b: Vec3) -> Double {
    acos(min(1, abs(simd_dot(a, b)) / simd_length(a) / simd_length(b))) * 180 / .pi
}

// PRNG parity
let prng = fixture("prng.json")
var random = FloorCalibration.Mulberry32(seed: UInt32((prng["seed"] as! NSNumber).intValue))
for value in doubles(prng["values"]) { near(random.next(), value, 1e-11, "mulberry32") }

// Jacobi
let A: [[Double]] = [[4, 1, 0.5], [1, 3, 0.2], [0.5, 0.2, 1]]
let eigen = FloorCalibration.symmetricEigen(A)
check(eigen.values[0] <= eigen.values[1] && eigen.values[1] <= eigen.values[2], "eigen order")
for (k, v) in eigen.vectors.enumerated() {
    let Av = A.map { $0[0] * v.x + $0[1] * v.y + $0[2] * v.z }
    nearAll(Av, [v.x, v.y, v.z].map { $0 * eigen.values[k] }, 1e-10, "eigen")
}
print("PRNG and eigen parity passed")

// Yaw (plan section 3)
let yaw = fixture("yaw_cases.json")
for case let c as [String: Any] in yaw["cases"] as! [Any] {
    let name = c["name"] as! String
    let position = vec(c["position"]), normal = vec(c["normal"]), camera = vec(c["camera"])
    let heading = SurfacePose.horizontalHeading(origin: position, camera: camera)!
    nearAll(MatrixMath.vector(heading), doubles(c["heading"]), 1e-9, name)
    let frame = SurfacePose.rowFrame(origin: position, normal: normal, heading: heading)!
    nearAll(MatrixMath.array(frame.matrix), doubles(c["matrix"]), 1e-9, name)
    near(frame.alongRowInclination, (c["alongRowInclination"] as! NSNumber).doubleValue, 1e-9, name)
    near(frame.crossSlope, (c["crossSlope"] as! NSNumber).doubleValue, 1e-9, name)
    let x = MatrixMath.axis(frame.matrix, 0)
    near(x.x * heading.x + x.z * heading.z, 0, 1e-12, "\(name) plan-view perpendicular")
    nearAll(MatrixMath.array(SurfacePose.pose(position: position, normal: normal, camera: camera)!), doubles(c["matrix"]), 1e-9, name)
    let lower = SurfacePose.pose(position: position, normal: normal, camera: Vec3(camera.x, position.y + 0.4, camera.z))!
    nearAll(MatrixMath.array(lower), doubles(c["matrix"]), 1e-9, "\(name) camera height")
}
for case let c as [String: Any] in yaw["rejects"] as! [Any] {
    check(SurfacePose.pose(position: vec(c["position"]), normal: vec(c["normal"]), camera: vec(c["camera"])) == nil, c["name"] as! String)
}
print("Yaw/inclination composition passed")

// Floor calibration
for case let c as [String: Any] in fixture("plane_fit_cases.json")["cases"] as! [Any] {
    let name = c["name"] as! String
    let observations = (c["observations"] as! [[String: Any]]).map { o in
        FloorCalibration.Observation(point: vec(o["point"]), camera: vec(o["camera"]), source: o["source"] as! String,
            batch: (o["batch"] as! NSNumber).intValue, epoch: (o["epoch"] as! NSNumber).intValue,
            receivedTimestamp: (o["receivedTimestamp"] as! NSNumber).doubleValue)
    }
    let result = FloorCalibration.fit(observations: observations, origin: vec(c["origin"]), heading: vec(c["heading"]),
                                      gravityUp: vec(c["gravityUp"]), epoch: (c["epoch"] as! NSNumber).intValue)
    let expect = c["expect"] as! [String: Any]
    check((expect["status"] as! [String]).contains(result.status.rawValue), "\(name): \(result.status) \(result.reasons)")
    if let tolerance = (expect["normalToleranceDeg"] as? NSNumber)?.doubleValue {
        check(angleDeg(result.normal!, vec(c["trueNormal"])) <= tolerance, "\(name) normal")
        near(result.alongRowInclination!, (c["trueAlongRowInclination"] as! NSNumber).doubleValue, tolerance, name)
    }
    if let source = expect["source"] as? String { check(result.source == source, "\(name) source") }
    if let batches = expect["batches"] as? NSNumber { check(result.batches == batches.intValue, "\(name) batches") }
    check(result.limitations.contains { $0.hasPrefix("precision unverified") }, name)
    if let physical = (c["physicalAlongRowInclination"] as? NSNumber)?.doubleValue {
        check(abs(result.alongRowInclination! - physical) > 0.2, "\(name): bias must not be hidden")
        check((result.robustResidualM ?? 1) < 0.01, "\(name) residual")
    }
}
print("Floor calibration: pitched, compound, outliers, discontinuity, source bias, collinear, stale epoch passed")

// Budget
let budget = fixture("budget_cases.json")
for case let c as [String: Any] in budget["cases"] as! [Any] {
    let b = AccuracyBudget(width: (c["width"] as! NSNumber).doubleValue, rectangleCount: (c["count"] as! NSNumber).intValue)
    near(b.radiusM, (c["radiusM"] as! NSNumber).doubleValue)
    near(b.verticalAngleAllowanceDeg, (c["verticalAngleAllowanceDeg"] as! NSNumber).doubleValue)
    near(b.horizontalRotationAllowanceDeg, (c["horizontalRotationAllowanceDeg"] as! NSNumber).doubleValue)
}
for case let d as [String: Any] in budget["displacement"] as! [Any] {
    near(AccuracyBudget.rotationDisplacementM((d["errorDeg"] as! NSNumber).doubleValue, (d["radiusM"] as! NSNumber).doubleValue),
         (d["displacementM"] as! NSNumber).doubleValue)
}
print("Accuracy budget passed")

// Height correction
let height = fixture("height_correction_cases.json")
let base = mat(height["base"])
let applied = HeightCorrector(), shadow = HeightCorrector()
var lastApplied = 0.0
for case let step as [String: Any] in height["steps"] as! [Any] {
    let observations = (step["observations"] as! [[String: Any]]).map { o in
        HeightCorrector.Observation(point: vec(o["point"]), normal: o["normal"].map { vec($0) }, source: o["source"] as! String,
            targetMissM: (o["targetMissM"] as! NSNumber).doubleValue, cycle: (o["cycle"] as! NSNumber).intValue)
    }
    let time = (step["time"] as! NSNumber).doubleValue
    let update = applied.update(base: base, observations: observations, now: time, apply: true)
    check(update.residuals.count == (step["expectedResidualCount"] as! NSNumber).intValue, "residual count")
    check(update.rejected.count == (step["expectedRejected"] as! NSNumber).intValue, "rejected count")
    if let proposed = step["expectedProposedM"] as? NSNumber { near(update.proposedDeltaM!, proposed.doubleValue) }
    else { check(update.proposedDeltaM == nil, "no proposal yet") }
    lastApplied = (step["expectedAppliedM"] as! NSNumber).doubleValue
    near(update.appliedDeltaM, lastApplied)
    check(shadow.update(base: base, observations: observations, now: time, apply: false).appliedDeltaM == 0, "shadow never applies")
}
let origin = MatrixMath.position(base)
near(HeightCorrector.residual(base: base, point: origin + Vec3(0, 0.03, 0))!, 0.03, 1e-12)
let corrected = HeightCorrector.corrected(base: base, appliedDeltaM: 0.03)
near(MatrixMath.position(corrected).y - origin.y, 0.03, 1e-12)
nearAll(Array(MatrixMath.array(corrected)[0..<12]), Array(MatrixMath.array(base)[0..<12]), 1e-15)
applied.markStale()
let held = applied.update(base: base, observations: [], now: 99, apply: true)
check(held.stale, "stale")
near(held.appliedDeltaM, lastApplied)
applied.reset()
check(applied.appliedDeltaM == 0, "reset clears offset")
print("Height correction: gates, rate limit, shadow isolation, stale/reset passed")

// Survey import
var validManifest: SurveyManifest?
for case let c as [String: Any] in fixture("survey_manifests.json")["cases"] as! [Any] {
    let name = c["name"] as! String
    switch SurveyManifest.validate(c["manifest"]) {
    case .ok(let manifest):
        check(c["ok"] as! Bool, "\(name) should fail")
        check(angleDeg(manifest.floor.normal, vec(c["floorNormal"])) < 1e-5, "\(name) floor normal")
    case .failed(let errors):
        check(!(c["ok"] as! Bool), "\(name): \(errors)")
        check(errors.contains(c["error"] as! String), "\(name): \(errors)")
    }
}
print("Survey import passed")

// Fusion
let fusion = fixture("fusion_cases.json")
guard case .ok(let manifest) = SurveyManifest.validate(fusion["manifest"]) else { fatalError("fusion manifest") }
validManifest = manifest
func observations(_ list: Any?) -> [ReferenceFusion.Observation] {
    (list as! [[String: Any]]).map { o in
        ReferenceFusion.Observation(id: o["id"] as! String, worldFromMarker: mat(o["worldFromMarker"]),
            timestamp: (o["timestamp"] as! NSNumber).doubleValue, epoch: (o["epoch"] as! NSNumber).intValue, tracking: o["tracking"] as! Bool)
    }
}
let cases = fusion["cases"] as! [[String: Any]]
for c in cases {
    let name = c["name"] as! String
    let result = ReferenceFusion.fuse(manifest: manifest, observations: observations(c["observations"]),
        now: (c["now"] as! NSNumber).doubleValue, epoch: (c["epoch"] as! NSNumber).intValue)
    check(result.used == c["used"] as! [String], "\(name) used \(result.used)")
    check(result.observability == c["observability"] as! String, "\(name) observability")
    if let rejected = c["rejected"] as? [String] { check(Array(Set(result.rejected.map(\.id))).sorted() == rejected, "\(name) rejected") }
    if c["expected"] is NSNull { check(result.worldFromSurvey == nil, "\(name) expected no pose") }
    else {
        let d = MatrixMath.difference(result.worldFromSurvey!, mat(c["expected"]))
        check(d.positionM <= (c["toleranceM"] as! NSNumber).doubleValue && d.rotationDeg <= (c["toleranceDeg"] as! NSNumber).doubleValue, "\(name) \(d)")
    }
    for (id, value) in c["validation"] as? [String: NSNumber] ?? [:] {
        near(result.validation.first { $0.id == id }!.positionM, value.doubleValue, 1e-9, name)
    }
}
// Controller: surveyed floor authority and one root
let worldFromSurvey = mat(fusion["worldFromSurvey"])
let controller = ReferenceFrameController(manifest: manifest)
observations(cases[1]["observations"]).forEach(controller.observe)
check(controller.update(now: 10.1, epoch: 1, worldFromAnchorNow: nil) == .tracking, "tracking")
let tilt = tan(1.5 * Double.pi / 180)
let surveyHit = Vec3(3, 3 * tilt + 0.2, 0.3)
guard case .placed(let surveyFromRow) = controller.placeRow(hitWorld: MatrixMath.transform(worldFromSurvey, surveyHit),
    cameraWorld: MatrixMath.transform(worldFromSurvey, Vec3(3, 1.8, 2.5))) else { fatalError("survey placement") }
nearAll(MatrixMath.vector(MatrixMath.axis(surveyFromRow, 1)), MatrixMath.vector(manifest.floor.normal), 1e-12, "survey normal")
near(simd_dot(manifest.floor.normal, MatrixMath.position(surveyFromRow) - manifest.floor.point), 0, 1e-9, "origin on survey floor")
controller.commit(surveyFromRow: surveyFromRow, worldFromAnchorNow: nil)
nearAll(MatrixMath.array(controller.worldFromRow!), MatrixMath.array(worldFromSurvey * surveyFromRow), 1e-9, "one root")
if case .placed = controller.placeRow(hitWorld: Vec3(100, 0, 100), cameraWorld: Vec3(100, 1.6, 102)) { check(false, "extent") }
check(controller.update(now: 20, epoch: 1, worldFromAnchorNow: nil) == .stale, "stale after loss")
print("Reference fusion and controller passed")

// Anchor transport (plan section 6)
let transport = fixture("transport_cases.json")
let q = doubles(transport["anchorQuaternion"])
let anchor = MatrixMath.matrix(position: vec(transport["anchorPosition"]), quaternion: SIMD4(q[0], q[1], q[2], q[3]))!
nearAll(MatrixMath.array(anchor), doubles(transport["anchor"]), 1e-9, "quaternion")
let placed = mat(transport["placed"])
let referenceFromRow = MatrixMath.inverseRigid(anchor) * placed
nearAll(MatrixMath.array(referenceFromRow), doubles(transport["referenceFromRow"]), 1e-9, "referenceFromRow")
nearAll(MatrixMath.array(anchor * referenceFromRow), MatrixMath.array(placed), 1e-9, "first render")
for (update, rendered) in zip(transport["updates"] as! [Any], transport["rendered"] as! [Any]) {
    nearAll(MatrixMath.array(mat(update) * referenceFromRow), doubles(rendered), 1e-9, "transport")
}
check(MatrixMath.difference(mat(transport["naiveFirstRender"]), placed).positionM > 0.01, "naive baseline jumps")
let qBack = MatrixMath.quaternion(anchor)
nearAll([qBack.x, qBack.y, qBack.z, qBack.w], q, 1e-9, "quaternion roundtrip")
print("Anchor transport passed")
